assign verify_read_word=read_word;assign verify_read_position=read_position;
assign verify_read_address=read_address;assign verify_read_segment=read_segment;assign verify_read_band=read_band;
assign verify_position_use=state==AC_EXTRACT && !cancel && !response_failure &&
    cache_valid[read_segment] && cache_address[read_segment]==18'(read_address & 32'hfffffff0);
for(genvar b=0;b<4;b=b+1)begin: observed_cache
    assign verify_cache_data[b*128+:128]=cache_data[b];
    for(genvar o=0;o<16;o=o+1)begin: observed_offset
        logic [18:0] geometry;
        assign geometry=19'(cache_data[b]>>(8*o+13));
        assign verify_positions[(b*16+o)*19+:19]={geometry[18:6],zigzag(geometry[5:0])};
    end
