    assign verify_heads[(b-1)*32+:32]=heads[b];
    assign verify_cursors[(b-1)*32+:32]=cursors[b];
    assign verify_head_positions[(b-1)*19+:19]={heads[b][31:19],zigzag(heads[b][18:13])};
end
